/** IUH diamond border strip, generated at runtime (1080×110). */
function makeDiamondStrip(variant: "top" | "bottom"): string {
  const W = 1080;
  const H = 72;
  const canvas = document.createElement("canvas");
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext("2d");
  if (!ctx) return "";
  // IUH blue band so the white diamonds stay visible on light backgrounds.
  ctx.fillStyle = "#1e3f96";
  ctx.fillRect(0, 0, W, H);
  const gold = "#f2b705";
  const light = "#7fb2e5";
  const white = "#ffffff";
  const seq = variant === "top" ? [gold, light, white, light] : [light, white, light, gold];
  const dw = 135;
  let n = 0;
  for (let x = -dw / 2; x < W + dw / 2; x += dw / 2, n++) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x + dw / 2, H / 2);
    ctx.lineTo(x, H);
    ctx.lineTo(x - dw / 2, H / 2);
    ctx.closePath();
    ctx.fillStyle = seq[n % seq.length];
    ctx.fill();
  }
  return canvas.toDataURL("image/png");
}

let stripCache: { top: string; bottom: string } | null = null;
function getDiamondStrips(): { top: string; bottom: string } {
  if (!stripCache) stripCache = { top: makeDiamondStrip("top"), bottom: makeDiamondStrip("bottom") };
  return stripCache;
}

/** Solid color block (header ribbon, vertical divider…) generated at runtime. */
function makeSolid(w: number, h: number, color: string): string {
  const canvas = document.createElement("canvas");
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext("2d");
  if (!ctx) return "";
  ctx.fillStyle = color;
  ctx.fillRect(0, 0, w, h);
  return canvas.toDataURL("image/png");
}

const solidCache = new Map<string, string>();
function getSolid(w: number, h: number, color: string): string {
  const key = `${w}x${h}:${color}`;
  let url = solidCache.get(key);
  if (!url) {
    url = makeSolid(w, h, color);
    solidCache.set(key, url);
  }
  return url;
}

/** Light photo-slot placeholder, generated at the slot's aspect ratio. */
function makePhotoPlaceholder(W = 1080, H = 470): string {
  const canvas = document.createElement("canvas");
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext("2d");
  if (!ctx) return "";
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, "#eef1f7");
  g.addColorStop(1, "#dde3ee");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
  // faint diamond hint, echoing the IUH pattern
  ctx.fillStyle = "rgba(30,63,150,0.06)";
  const dw = 120;
  for (let x = -dw / 2; x < W + dw / 2; x += dw / 2) {
    for (let y = 0; y < H + 60; y += 120) {
      ctx.beginPath();
      ctx.moveTo(x, y - 45);
      ctx.lineTo(x + dw / 2, y);
      ctx.lineTo(x, y + 45);
      ctx.lineTo(x - dw / 2, y);
      ctx.closePath();
      ctx.fill();
    }
  }
  ctx.textAlign = "center";
  ctx.fillStyle = "#8fa8d8";
  const iconSize = Math.min(110, H * 0.24, W * 0.2);
  ctx.font = `${iconSize}px system-ui, sans-serif`;
  ctx.fillText("📷", W / 2, H / 2 - H * 0.06);
  // shrink text to fit the slot width
  const fit = (text: string, maxW: number, base: number, weight: string) => {
    let size = base;
    ctx.font = `${weight} ${size}px system-ui, sans-serif`;
    while (ctx.measureText(text).width > maxW && size > 8) {
      size -= 2;
      ctx.font = `${weight} ${size}px system-ui, sans-serif`;
    }
    return size;
  };
  const title = "THÊM ẢNH HOẠT ĐỘNG";
  const sub = "Nhấn vào ảnh → nút “🔄 Thay ảnh” để đổi ảnh thật";
  ctx.fillStyle = "#5b6b8c";
  const tSize = fit(title, W * 0.88, Math.min(44, H * 0.1), "bold");
  ctx.font = `bold ${tSize}px system-ui, sans-serif`;
  ctx.fillText(title, W / 2, H / 2 + H * 0.13);
  ctx.fillStyle = "#8a93a8";
  const sSize = fit(sub, W * 0.9, Math.min(30, H * 0.065), "");
  ctx.font = `${sSize}px system-ui, sans-serif`;
  ctx.fillText(sub, W / 2, H / 2 + H * 0.245);
  return canvas.toDataURL("image/png");
}

const photoPlaceholderCache = new Map<string, string>();
function getPhotoPlaceholder(w = 1080, h = 470): string {
  const key = `${Math.round(w)}x${Math.round(h)}`;
  let url = photoPlaceholderCache.get(key);
  if (!url) {
    url = makePhotoPlaceholder(Math.round(w), Math.round(h));
    photoPlaceholderCache.set(key, url);
  }
  return url;
}

